/* Model 2 prototype inference - see model2_infer.h. SYNTHETIC PROTOTYPE. */
#include "model2_infer.h"

#include <math.h>
#include <string.h>

#include "model2_logreg_params.h" /* generated by scripts/model2_export.py */

const char *m2_class_name(int cls) {
    switch (cls) {
        case M2_LOW: return "LOW";
        case M2_MEDIUM: return "MEDIUM";
        case M2_HIGH: return "HIGH";
        default: return "UNAVAILABLE";
    }
}

m2_status_t m2_predict(const m2_raw_t *in, float probs[3], int *cls) {
    if (!in || !probs || !cls) return M2_ERR_NULL;
    memset(probs, 0, sizeof(float) * M2_N_CLASSES);
    *cls = -1;

    const float raw[8] = {in->tcs_r, in->tcs_g, in->tcs_b, in->tcs_c,
                          in->mq135, in->ph,   in->temp_c, in->humidity_pct};
    for (int i = 0; i < 8; ++i)
        if (!isfinite(raw[i])) return M2_ERR_NONFINITE;
    if (in->tcs_c <= 0.0f || in->mq135 <= 0.0f) return M2_ERR_DOMAIN;

    /* Feature order must match M2 export: 8 raw + 4 derived. */
    float x[M2_N_FEATURES];
    for (int i = 0; i < 8; ++i) x[i] = raw[i];
    x[8] = in->tcs_r / in->tcs_c;
    x[9] = in->tcs_g / in->tcs_c;
    x[10] = in->tcs_b / in->tcs_c;
    x[11] = logf(in->mq135);

    float logits[M2_N_CLASSES];
    float maxl = -INFINITY;
    for (int k = 0; k < M2_N_CLASSES; ++k) {
        float s = M2_INTERCEPT[k];
        for (int j = 0; j < M2_N_FEATURES; ++j)
            s += M2_COEF[k][j] * ((x[j] - M2_MEAN[j]) / M2_SCALE[j]);
        logits[k] = s;
        if (s > maxl) maxl = s;
    }
    float sum = 0.0f;
    for (int k = 0; k < M2_N_CLASSES; ++k) {
        probs[k] = expf(logits[k] - maxl); /* numerically stable softmax */
        sum += probs[k];
    }
    int best = 0;
    for (int k = 0; k < M2_N_CLASSES; ++k) {
        probs[k] /= sum;
        if (probs[k] > probs[best]) best = k;
    }
    *cls = best;
    return M2_OK;
}
